public static Node<Integer> insertSorted(Node<Integer> first, int x) {
    Node<Integer> node = new Node<Integer>(x);
    if (first == null || x <= first.getValue()) {
        node.setNext(first);
        return node;
    }
    Node<Integer> p = first;
    while (p.getNext() != null && p.getNext().getValue() < x) {
        p = p.getNext();
    }
    node.setNext(p.getNext());
    p.setNext(node);
    return first;
}

public static void removeDuplicates(Node<Integer> first) {
    Node<Integer> p = first;
    while (p.getNext() != null) {
        if (p.getNext().getValue().equals(p.getValue())) {
            p.setNext(p.getNext().getNext());
        } else {
            p = p.getNext();
        }
    }
}

